// CI only (copied to test/ci/ by scripts/sandbox.sh): every curated palette
// (assets/palettes/curated.json), applied with the seeds palette.py writes,
// builds a theme that passes the harness's contrast and soft-container
// checks in light and dark mode, and keeps the hues it was given.
// curated_palettes.dart is generated by ci/palette_cases.py.

import 'package:app/design_system/design_system.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import '../ui/ui_harness.dart';
import 'curated_palettes.dart';

double _hue(Color color) => HSVColor.fromColor(color).hue;

double _hueDistance(double a, double b) {
  final d = (a - b).abs() % 360;
  return d > 180 ? 360 - d : d;
}

void main() {
  test('there are curated palettes to check', () {
    expect(curatedPalettes.length, greaterThanOrEqualTo(20));
  });

  for (final palette in curatedPalettes) {
    for (final brightness in Brightness.values) {
      test('palette ${palette.name}: ${brightness.name}', () {
        final config = AppThemeConfig(
          seed: palette.seed,
          variant: DynamicSchemeVariant.fidelity,
          secondarySeed: palette.secondary,
          tertiarySeed: palette.tertiary,
          neutralSeed: palette.neutral,
        );
        final s = AppTheme.build(brightness, platform: TargetPlatform.android, config: config).colorScheme;
        final failures = <String>[];

        void check(String name, Color foreground, Color background, double minimum) {
          final ratio = contrastRatio(foreground, background);
          if (ratio < minimum) failures.add('$name: ${ratio.toStringAsFixed(2)}:1 (needs $minimum:1)');
        }

        for (final (name, surface) in [
          ('surface', s.surface),
          ('surfaceContainerLowest', s.surfaceContainerLowest),
          ('surfaceContainer', s.surfaceContainer),
          ('surfaceContainerHighest', s.surfaceContainerHighest),
        ]) {
          check('onSurface on $name', s.onSurface, surface, 4.5);
          check('onSurfaceVariant on $name', s.onSurfaceVariant, surface, 4.5);
          check('primary on $name', s.primary, surface, 4.5);
          check('outline on $name', s.outline, surface, 3);
          check('tertiary (accent marks) on $name', s.tertiary, surface, 3);
        }
        check('onPrimary on primary', s.onPrimary, s.primary, 4.5);
        check('onSecondary on secondary', s.onSecondary, s.secondary, 4.5);
        check('onTertiary on tertiary', s.onTertiary, s.tertiary, 4.5);
        check('onSecondaryContainer on secondaryContainer', s.onSecondaryContainer, s.secondaryContainer, 4.5);
        check('onTertiaryContainer on tertiaryContainer', s.onTertiaryContainer, s.tertiaryContainer, 4.5);
        for (final (name, color) in [
          ('primaryContainer', s.primaryContainer),
          ('secondaryContainer', s.secondaryContainer),
          ('tertiaryContainer', s.tertiaryContainer),
        ]) {
          final problem = softContainerProblem(color, brightness);
          if (problem != null) failures.add('$name $problem');
        }

        // The palette's hues survive: the primary and the accent are the
        // colors that were chosen, not Material's guesses.
        if (brightness == Brightness.light) {
          if (_hueDistance(_hue(s.primary), _hue(palette.seed)) > 20) failures.add('primary lost its hue');
          final tertiary = palette.tertiary;
          if (tertiary != null && _hueDistance(_hue(s.tertiary), _hue(tertiary)) > 25) failures.add('accent lost its hue');
        }

        expect(failures, isEmpty, reason: '\n${failures.join('\n')}');
      });
    }
  }
}
